-- 004: enforce project identity across relational references, even within one organisation.
update schema_migrations set version='001_core.sql' where version='001_core';
create function check_references() returns trigger language plpgsql security definer set search_path=public as $$
declare col_name text; target_table text; ref_id uuid; ref_project uuid;
begin
if TG_TABLE_NAME='dataset_versions' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'dataset_id')::uuid; if ref_id is not null then select project_id into ref_project from datasets where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'dataset_id'; end if; end if; end if;
if TG_TABLE_NAME='data_import_jobs' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'dataset_id')::uuid; if ref_id is not null then select project_id into ref_project from datasets where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'dataset_id'; end if; end if; end if;
