if TG_TABLE_NAME='experiments' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'dataset_version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'dataset_version_id'; end if; end if; end if;
if TG_TABLE_NAME='experiment_runs' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'experiment_id')::uuid; if ref_id is not null then select project_id into ref_project from experiments where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'experiment_id'; end if; end if; end if;
