if TG_TABLE_NAME='recommendation_evidence' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'recommendation_id')::uuid; if ref_id is not null then select project_id into ref_project from recommendations where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'recommendation_id'; end if; end if; end if;
