if TG_TABLE_NAME='operational_alerts' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'evidence_id')::uuid; if ref_id is not null then select project_id into ref_project from evidence_records where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'evidence_id'; end if; end if; end if;
if TG_TABLE_NAME='action_items' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'alert_id')::uuid; if ref_id is not null then select project_id into ref_project from operational_alerts where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'alert_id'; end if; end if; end if;
if TG_TABLE_NAME='action_items' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'recommendation_id')::uuid; if ref_id is not null then select project_id into ref_project from recommendations where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'recommendation_id'; end if; end if; end if;
if TG_TABLE_NAME='budgets' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'version_id'; end if; end if; end if;
if TG_TABLE_NAME='funding_releases' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'version_id'; end if; end if; end if;
