if TG_TABLE_NAME='expenditure_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'version_id'; end if; end if; end if;
if TG_TABLE_NAME='expenditure_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'budget_id')::uuid; if ref_id is not null then select project_id into ref_project from budgets where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'budget_id'; end if; end if; end if;
if TG_TABLE_NAME='inventory_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'version_id'; end if; end if; end if;
if TG_TABLE_NAME='inventory_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'facility_id')::uuid; if ref_id is not null then select project_id into ref_project from facilities where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'facility_id'; end if; end if; end if;
if TG_TABLE_NAME='inventory_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'product_id')::uuid; if ref_id is not null then select project_id into ref_project from medicine_products where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'product_id'; end if; end if; end if;
if TG_TABLE_NAME='consumption_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'version_id')::uuid; if ref_id is not null then select project_id into ref_project from dataset_versions where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'version_id'; end if; end if; end if;
if TG_TABLE_NAME='consumption_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'facility_id')::uuid; if ref_id is not null then select project_id into ref_project from facilities where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'facility_id'; end if; end if; end if;
if TG_TABLE_NAME='consumption_records' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'product_id')::uuid; if ref_id is not null then select project_id into ref_project from medicine_products where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'product_id'; end if; end if; end if;
if TG_TABLE_NAME='deliveries' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'facility_id')::uuid; if ref_id is not null then select project_id into ref_project from facilities where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'facility_id'; end if; end if; end if;
if TG_TABLE_NAME='deliveries' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'product_id')::uuid; if ref_id is not null then select project_id into ref_project from medicine_products where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'product_id'; end if; end if; end if;
if TG_TABLE_NAME='optimisation_scenarios' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'recommendation_id')::uuid; if ref_id is not null then select project_id into ref_project from recommendations where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'recommendation_id'; end if; end if; end if;
if TG_TABLE_NAME='learning_progress' and TG_OP!='DELETE' then ref_id := (to_jsonb(NEW)->>'module_id')::uuid; if ref_id is not null then select project_id into ref_project from learning_modules where id=ref_id; if ref_project is distinct from NEW.project_id then raise exception 'Cross-project reference: %.%', TG_TABLE_NAME, 'module_id'; end if; end if; end if;
return NEW; end $$;
